<?php
namespace CGM\Core\REST;use CGM\Core\Plugin;
final class RegistryController extends BaseController {
    public function __construct(private Plugin $core){}
    public function register_routes():void{register_rest_route($this->namespace,'/registry',array('methods'=>\WP_REST_Server::READABLE,'callback'=>fn()=>rest_ensure_response($this->payload(true)),'permission_callback'=>fn()=>current_user_can('inspect_cgm_core')||$this->can_manage()));register_rest_route($this->namespace,'/registry/editor',array('methods'=>\WP_REST_Server::READABLE,'callback'=>fn()=>rest_ensure_response($this->payload(false)),'permission_callback'=>fn()=>current_user_can('inspect_cgm_core')||$this->can_manage()||current_user_can('manage_cgm_queries')));}
    private function payload(bool $full):array{$providers=$this->core->providers()->all();$dependencies=$this->core->providers()->dependency_report();if(!$full){foreach($providers as &$p){unset($p['notes']);}unset($p);}return array('version'=>CGM_CORE_VERSION,'api'=>array('core'=>CGM_CORE_API_VERSION,'query'=>CGM_CORE_QUERY_API_VERSION,'relationships'=>CGM_CORE_RELATIONSHIP_API_VERSION,'dynamic_data'=>CGM_CORE_DYNAMIC_DATA_API_VERSION),'schema'=>CGM_CORE_SCHEMA_VERSION,'providers'=>$providers,'provider_compatibility'=>$dependencies,'builders'=>$this->core->builders()->all(),'query_providers'=>array_keys($this->core->query_providers()->all()),'content_types'=>$this->core->content_types()->all(),'fields'=>$this->core->fields()->all(),'relationships'=>$this->core->relationships()->all(),'dynamic_data'=>$this->core->dynamic_data()->serialize(),'context_tokens'=>$this->core->context()->tokens(),'multisite'=>$this->core->multisite()->describe());}
}
